UPDATE t_refund
SET status = 'PROCESSING', channel_refund_no = #{channelRefundNo}
WHERE refund_no = #{refundNo} AND status = 'CREATED'

UPDATE t_refund
SET status = 'CREATED', retry_count = #{retryCount}, operator = #{operator}
WHERE refund_no = #{refundNo} AND status = 'FAILED'

UPDATE t_refund
SET status = 'SUCCESS', success_time = #{successTime}, channel_refund_no = #{channelRefundNo}
WHERE refund_no = #{refundNo} AND status = #{fromStatus}

UPDATE t_refund
SET status = 'FAILED', fail_time = #{failTime}
WHERE refund_no = #{refundNo} AND status = #{fromStatus}

